const JSON_ONLY = "";
const formatResults = () => "";

/**
 * The check itself: prompt, parse, normalise. No fetch, no DOM, no Node.
 *
 * Shared by two callers that live in different runtimes — the browser during
 * development, and the scheduled worker in production. Keeping it free of both
 * means the site and the cron job can never drift into asking different
 * questions or accepting different answers.
 */

/**
 * The three top-level tabs. Every entry belongs to exactly one, assigned by the
 * model. `type` is the finer, model-invented label that filters within a tab.
 */
const SECTIONS = [
  {
    id: "business",
    label: "AI Business",
    brief: "funding, acquisitions, earnings, regulation, hiring, market moves, company strategy",
  },
  {
    id: "product",
    label: "Product Releases",
    brief:
      "anything shipped and usable today: model releases, API and SDK changes, tooling, pricing, deprecations, protocol and spec revisions",
  },
  {
    id: "innovation",
    label: "Innovations",
    brief:
      "research and new techniques, whether or not shipped: papers, benchmarks, architectures, novel methods, hardware research",
  },
];

/** Used when the model omits a section or invents one we don't recognise. */
const SECTION_BY_TYPE = {
  "Model release": "product",
  "API & tooling": "product",
  Pricing: "product",
  Deprecation: "product",
  Protocol: "product",
  Research: "innovation",
  Industry: "business",
};

function sectionFor(entry) {
  const given = String(entry.section || "").toLowerCase();
  if (SECTIONS.some((s) => s.id === given)) return given;
  return SECTION_BY_TYPE[entry.type] || "product";
}

const TAXONOMY = [
  "Model release",
  "API & tooling",
  "Pricing",
  "Deprecation",
  "Protocol",
  "Research",
  "Industry",
];

/**
 * Model families the wire filters by. `label` is what the chip says; `match`
 * are the strings that identify the family in an entry's own words.
 *
 * Families, not versions: "Claude", not "Claude Opus 5" — a filter with one
 * entry behind it is noise, and someone narrowing to Claude wants every Claude
 * item, not a particular release.
 *
 * Order is roughly by how often the wire's sources mention them.
 */
const MODEL_FAMILIES = [
  // `match`  — terms that name the family or one of its models, matched on
  //            word boundaries so "sol" can't hit "solution".
  // `vendor` — values of an entry's `source` field that imply the family. An
  //            Anthropic SDK change is a Claude concern even when no model is
  //            named, and `source` is structured, so matching it is safe.
  {
    id: "claude",
    label: "Claude",
    match: ["claude", "opus", "sonnet", "haiku", "fable", "mythos"],
    vendor: ["anthropic"],
  },
  {
    id: "gpt",
    label: "GPT",
    match: ["gpt", "chatgpt", "codex", "sol", "luna", "terra"],
    vendor: ["openai"],
  },
  {
    id: "gemini",
    label: "Gemini",
    match: ["gemini", "nano banana", "veo", "imagen", "lyria"],
    vendor: ["google", "google deepmind"],
  },
  { id: "llama", label: "Llama", match: ["llama"], vendor: [] },
  { id: "muse", label: "Muse", match: ["muse"], vendor: [] },
  { id: "gemma", label: "Gemma", match: ["gemma"], vendor: [] },
  {
    id: "mistral",
    label: "Mistral",
    match: ["mistral", "ministral", "codestral", "voxtral", "magistral"],
    vendor: ["mistral"],
  },
  { id: "qwen", label: "Qwen", match: ["qwen"], vendor: [] },
  { id: "deepseek", label: "DeepSeek", match: ["deepseek"], vendor: ["deepseek"] },
  { id: "kimi", label: "Kimi", match: ["kimi"], vendor: [] },
  { id: "glm", label: "GLM", match: ["glm"], vendor: [] },
  { id: "grok", label: "Grok", match: ["grok"], vendor: ["xai"] },
  { id: "jev", label: "Jev", match: ["jev", "system one"], vendor: ["typesafe ai", "typesafe"] },
  { id: "nova", label: "Nova", match: ["nova"], vendor: [] },
  { id: "phi", label: "Phi", match: ["phi"], vendor: [] },
  { id: "command", label: "Command", match: ["command-r", "command r"], vendor: ["cohere"] },
];

const FAMILY_BY_ID = new Map(MODEL_FAMILIES.map((f) => [f.id, f]));

/** Word-boundary matcher per family, built once. */
const FAMILY_PATTERNS = new Map(
  MODEL_FAMILIES.map((f) => [
    f.id,
    new RegExp(
      `(^|[^a-z0-9])(${f.match.map((m) => m.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|")})([^a-z0-9]|$)`,
      "i"
    ),
  ])
);

/**
 * Which model families an entry concerns.
 *
 * Takes what the model reported, then falls back to scanning the entry's own
 * text. The fallback is what makes the filter work on entries written before
 * this field existed — and on a local model that ignored the field.
 *
 * An entry can legitimately touch several families (a comparison, a protocol
 * revision landing in three SDKs), and plenty touch none (a funding round, a
 * spec change), which is why this returns an array and never guesses one in.
 */
function modelsFor(entry) {
  const found = new Set();

  for (const given of Array.isArray(entry.models) ? entry.models : []) {
    const key = String(given).toLowerCase().trim();
    if (FAMILY_BY_ID.has(key)) {
      found.add(key);
    } else {
      // The model may answer with a label ("Claude") or a version
      // ("Claude Opus 5") rather than our id; match it like any other text.
      for (const [id, pattern] of FAMILY_PATTERNS) if (pattern.test(key)) found.add(id);
    }
  }

  const text = [entry.title, entry.summary].filter(Boolean).join(" ");
  for (const [id, pattern] of FAMILY_PATTERNS) if (pattern.test(text)) found.add(id);

  // The vendor's name counts wherever it appears, not just in `source`. A
  // funding story carried by a third party has the company in its title and
  // the outlet in its source, and someone filtering a family wants that story.
  const haystack = `${text} ${entry.source || ""}`.toLowerCase();
  for (const family of MODEL_FAMILIES) {
    if (family.vendor.some((v) => haystack.includes(v))) found.add(family.id);
  }

  return [...found];
}

const familyLabel = (id) => FAMILY_BY_ID.get(id)?.label || id;

function newestDate(known) {
  return known.map((i) => i.date).sort().slice(-1)[0] || "2026-08-01";
}

/**
 * @param {Array} known     entries already on the wire
 * @param {object} provider the selected provider
 * @param {Array} [results] pre-fetched search results; when present the model
 *                          is told to work only from them
 */
function buildPrompt(known, { supportsSearch }, results = null) {
  const newest = newestDate(known);
  const titles = known
    .slice(0, 25)
    .map((i) => `${i.date} ${i.source}: ${i.title}`)
    .join("\n");

  let sourcing;
  if (results?.length) {
    // Pre-search: retrieval already happened, so the model is a reader, not a
    // researcher. Naming the results as the only permitted source is what stops
    // a local model reaching for a plausible-looking URL from memory.
    sourcing = `Below are live web search results retrieved just now. Work ONLY from them. Every entry you return must use a url that appears verbatim in these results — never write a url that is not listed here, and never adjust one. Ignore results that are not a primary source (model or API docs, official changelogs and release notes, official research blogs, arXiv, SEC filings, the MCP specification), that are older than ${newest}, or that are already on the wire below. If none of the results qualify, return [].

SEARCH RESULTS
${formatResults(results)}`;
  } else if (supportsSearch) {
    sourcing = `Search the web for developments published AFTER ${newest} from primary sources only: model and API docs, official changelogs and release notes, official research blogs (Anthropic, OpenAI, Google DeepMind, Meta AI, Mistral), arXiv, SEC filings, and the MCP specification. Ignore social posts, listicles, and anything without a traceable primary source.`;
  } else {
    sourcing = `You cannot search. List only developments published AFTER ${newest} that you are confident about from your own knowledge, and give the canonical primary-source URL for each: official docs, changelogs, research blogs, or arXiv. If you are unsure a URL is real, omit the entry. Returning [] is the correct answer when you have nothing verifiable.`;
  }

  return `You maintain a changelog wire for a principal engineer who builds LLM systems: RAG, agent orchestration, evals, latency and observability, and the Anthropic/OpenAI/open-model APIs.

${sourcing}

Already on the wire, do not repeat:
${titles}

${JSON_ONLY} Up to 5 objects, each:
{"date":"YYYY-MM-DD","source":"Anthropic|OpenAI|Google|MCP|arXiv 1234.5678|...","tier":"Primary"|"Secondary","section":"exactly one of: ${SECTIONS.map(
    (x) => `${x.id} (${x.brief})`
  ).join(" | ")}","type":"one of: ${TAXONOMY.join(
    ", "
  )} — or a better short label you choose","models":["model FAMILIES this concerns, from: ${MODEL_FAMILIES.map(
    (f) => f.label
  ).join(", ")} — the family, never the version, so \\"Claude\\" not \\"Claude Opus 5\\"; several if it concerns several; [] for anything model-agnostic like a protocol change, a funding round, or a paper about no particular model"],"title":"under 70 chars, specific, version numbers kept","summary":"1-2 sentences on what it changes for someone building LLM systems, not marketing copy","url":"direct link to the announcement or paper","flagged":"omit unless the claim rests only on a vendor's own benchmark, then say so in under 6 words"}

If nothing qualifies, return [].`;
}

/** Models wrap JSON in prose or fences often enough that this stays defensive. */
function parseArray(text) {
  const cleaned = (text || "").replace(/```json|```/g, "").trim();
  const start = cleaned.indexOf("[");
  const end = cleaned.lastIndexOf("]");
  if (start < 0 || end < start) {
    // Some runtimes in JSON mode return a bare object wrapping the list.
    try {
      const arr = Object.values(JSON.parse(cleaned)).find(Array.isArray);
      return arr || [];
    } catch {
      return [];
    }
  }
  try {
    return JSON.parse(cleaned.slice(start, end + 1));
  } catch {
    return [];
  }
}

/** Drop repeats, coerce the fields the UI relies on, stamp the provider. */
function normalize(parsed, known, providerId) {
  const stamp = Date.now();
  const seen = new Set(known.map((i) => i.url + i.title));
  return (Array.isArray(parsed) ? parsed : [])
    .filter((x) => x && x.url && x.title && !seen.has(x.url + x.title))
    .map((x, n) => ({
      ...x,
      id: `live-${stamp}-${n}`,
      type: (x.type || "API & tooling").trim(),
      section: sectionFor(x),
      models: modelsFor(x),
      tier: x.tier === "Secondary" ? "Secondary" : "Primary",
      date: /^\d{4}-\d{2}-\d{2}$/.test(x.date || "")
        ? x.date
        : new Date().toISOString().slice(0, 10),
      via: providerId,
    }));
}

/* ────────────────────────────────────────────────────────────────────
   demo stubs — the real modules need a bundler and a server
   ──────────────────────────────────────────────────────────────────── */

/** In-memory: an artifact's localStorage belongs to one viewer and can throw. */
const memory = new Map();
const storage = {
  async get(key) {
    if (!memory.has(key)) throw new Error(`no entry for ${key}`);
    return { key, value: memory.get(key) };
  },
  async set(key, value) {
    memory.set(key, value);
    return { key, value };
  },
};

const PROVIDERS = [
  { id: "demo", label: "Demo", docs: "https://github.com/juubaker/ai-wire", models: ["seed entries"], supportsSearch: false },
];
const byId = () => PROVIDERS[0];
const DEFAULT_PROVIDER = "demo";
const isFeedMode = false;

async function fetchUpdates() {
  // Deliberately a thrown error rather than a silent no-op: the status line
  // then explains why nothing arrived instead of implying the wire is current.
  throw new Error(
    "this demo has no backend — the live site runs the check on a schedule"
  );
}

/* ────────────────────────────────────────────────────────────────────
   the app, inlined from src/App.jsx
   ──────────────────────────────────────────────────────────────────── */

const STORE_KEY = "items:v1";
const MODEL_KEY = "model:v1";
const POLL_MINUTES = Number(undefined || 5);
const POLL_MS = POLL_MINUTES * 60 * 1000;

const RANGES = [
  { id: "all", label: "All time", days: null },
  { id: "7", label: "7 days", days: 7 },
  { id: "30", label: "30 days", days: 30 },
  { id: "90", label: "90 days", days: 90 },
  { id: "custom", label: "Custom", days: null },
];

const iso = (d) => d.toISOString().slice(0, 10);

function fmtDate(d) {
  const t = new Date(d + "T00:00:00");
  if (isNaN(t)) return d;
  // The year is only shown when it isn't the current one — a changelog is
  // mostly recent, and repeating "2026" on every row is noise.
  const sameYear = t.getFullYear() === new Date().getFullYear();
  return t
    .toLocaleDateString(undefined, {
      month: "short",
      day: "numeric",
      ...(sameYear ? {} : { year: "numeric" }),
    })
    .toUpperCase();
}

/** Inclusive bounds for the active range, as YYYY-MM-DD strings or null. */
function bounds(range) {
  if (range.id === "custom") return { from: range.from || null, to: range.to || null };
  const preset = RANGES.find((r) => r.id === range.id);
  if (!preset?.days) return { from: null, to: null };
  const start = new Date();
  start.setDate(start.getDate() - preset.days);
  return { from: iso(start), to: null };
}

function fmtClock(ts) {
  if (!ts) return "never";
  return new Date(ts).toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
}

function Wire() {
  const [items, setItems] = useState(SEED);
  const [filter, setFilter] = useState("All");
  const [range, setRange] = useState({ id: "all", from: "", to: "" });
  const [tab, setTab] = useState("all");
  const [model, setModel] = useState("all");
  const [watching, setWatching] = useState(false);
  const [checking, setChecking] = useState(false);
  const [status, setStatus] = useState("Reading saved entries…");
  const [lastCheck, setLastCheck] = useState(null);
  const [newIds, setNewIds] = useState([]);
  // Learned from the first check: whether the server is pre-searching for us.
  const [searchMode, setSearchMode] = useState(null);
  const [choice, setChoice] = useState(() => {
    const p = byId(DEFAULT_PROVIDER);
    return { provider: p.id, model: p.models[0] };
  });
  // check() runs on a timer, so it reads the latest state through refs rather
  // than closing over a stale render. Refs are synced after commit, never
  // written during render.
  const itemsRef = useRef(items);
  const choiceRef = useRef(choice);
  useEffect(() => {
    itemsRef.current = items;
  }, [items]);
  useEffect(() => {
    choiceRef.current = choice;
  }, [choice]);
  const provider = byId(choice.provider);

  /* ---------- load anything saved from a previous visit ---------- */
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await storage.get(STORE_KEY);
        const saved = JSON.parse(res.value);
        if (!cancelled && saved && Array.isArray(saved.items)) {
          const seen = new Set(saved.items.map((i) => i.url + i.title));
          setItems([...saved.items, ...SEED.filter((s) => !seen.has(s.url + s.title))]);
          setLastCheck(saved.lastCheck || null);
        }
      } catch {
        /* nothing saved yet — the seed list stands */
      }
      try {
        const saved = JSON.parse((await storage.get(MODEL_KEY)).value);
        const p = byId(saved.provider);
        if (!cancelled) {
          setChoice({
            provider: p.id,
            model: p.models.includes(saved.model) ? saved.model : p.models[0],
          });
        }
      } catch {
        /* first visit — the default provider stands */
      }
      if (!cancelled) setStatus("Idle. Nothing checked yet this session.");
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const persist = useCallback(async (next, checkedAt) => {
    try {
      await storage.set(
        STORE_KEY,
        JSON.stringify({ items: next.slice(0, 120), lastCheck: checkedAt || null })
      );
    } catch {
      /* storage is a convenience here, not load-bearing */
    }
  }, []);

  const choose = useCallback((next) => {
    setChoice(next);
    storage.set(MODEL_KEY, JSON.stringify(next)).catch(() => {});
  }, []);

  /* ---------- ask the model what's new, and let it type each item ---------- */
  const check = useCallback(async () => {
    if (checking) return;
    setChecking(true);
    const active = byId(choiceRef.current.provider);
    setStatus(
      isFeedMode
        ? "Reading the shared feed…"
        : active.supportsSearch
          ? `Searching primary sources via ${active.label}…`
          : `${active.label} can't search the live web — asking for what it already knows, with sources.`
    );
    const known = itemsRef.current;

    try {
      const { fresh, checkedAt, mode, searched } = await fetchUpdates(known, choiceRef.current);
      const stamp = checkedAt || Date.now();

      if (fresh.length) {
        const next = [...fresh, ...known];
        setItems(next);
        setNewIds((p) => [...fresh.map((f) => f.id), ...p]);
        const how =
          mode === "injected" ? ` via ${active.label}, from ${searched} search results.` : mode === "memory" ? ` via ${active.label}, from memory — no search.` : isFeedMode ? " from the feed." : ` via ${active.label}.`;
        setSearchMode(mode ?? null);
        setStatus(`${fresh.length} new ${fresh.length === 1 ? "entry" : "entries"}${how}`);
        persist(next, stamp);
      } else {
        setSearchMode(mode ?? null);
        setStatus(
          isFeedMode
            ? "Feed is current — nothing new since the last check."
            : mode === "injected"
              ? `Nothing new in ${searched} search results.`
              : `Nothing new from primary sources, via ${active.label}.`
        );
        persist(known, stamp);
      }
      setLastCheck(stamp);
    } catch (err) {
      setStatus(
        isFeedMode ? `Couldn't read the feed: ${err.message}` : `${active.label} check failed: ${err.message}`
      );
    } finally {
      setChecking(false);
    }
  }, [checking, persist]);

  /* ---------- keep pulling while the tab stays open ---------- */
  useEffect(() => {
    if (!watching) return undefined;
    // Deferred, not called inline: an inline call would setState during the
    // effect body and cascade a second render before the first has painted.
    const kick = setTimeout(check, 0);
    const id = setInterval(check, POLL_MS);
    return () => {
      clearTimeout(kick);
      clearInterval(id);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [watching, choice.provider, choice.model]);

  // Date filtering happens first so the type counts describe what's actually
  // reachable in the current window, rather than the whole archive.
  // Entries written before sections existed, or returned without one, are
  // placed by their type rather than dropped.
  const placed = useMemo(
    () => items.map((i) => ({ ...i, section: sectionFor(i), models: modelsFor(i) })),
    [items]
  );

  const inTab = useMemo(
    () => (tab === "all" ? placed : placed.filter((i) => i.section === tab)),
    [placed, tab]
  );

  const inRange = useMemo(() => {
    const { from, to } = bounds(range);
    if (!from && !to) return inTab;
    return inTab.filter((i) => (!from || i.date >= from) && (!to || i.date <= to));
  }, [inTab, range]);

  // Tab counts respect the date range but not the type chip, so switching tabs
  // never lands on an empty list because of a type that doesn't exist there.
  const tabCounts = useMemo(() => {
    const { from, to } = bounds(range);
    const dated = placed.filter((i) => (!from || i.date >= from) && (!to || i.date <= to));
    const counts = { all: dated.length };
    SECTIONS.forEach((sec) => {
      counts[sec.id] = dated.filter((i) => i.section === sec.id).length;
    });
    return counts;
  }, [placed, range]);

  const matchesModel = (i) => model === "all" || (i.models || []).includes(model);
  const matchesType = (i) => filter === "All" || i.type === filter;

  // Each chip row counts against the OTHER row's active filter, so a count you
  // can see is always a count you can reach. Showing totals here instead would
  // let you click a chip and land on an empty list.
  const types = useMemo(() => {
    const counts = new Map();
    inRange.filter(matchesModel).forEach((i) => counts.set(i.type, (counts.get(i.type) || 0) + 1));
    return [...counts.entries()].sort((a, b) => b[1] - a[1]);
  }, [inRange, model]);

  const modelCounts = useMemo(() => {
    const counts = new Map();
    inRange.filter(matchesType).forEach((i) => {
      // An entry can belong to several families and is counted under each.
      (i.models || []).forEach((m) => counts.set(m, (counts.get(m) || 0) + 1));
    });
    return [...counts.entries()].sort((a, b) => b[1] - a[1]);
  }, [inRange, filter]);

  const shown = useMemo(() => {
    const list = inRange.filter((i) => matchesType(i) && matchesModel(i));
    return [...list].sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : 0));
  }, [inRange, filter, model]);

  // A chip that no longer matches anything would silently strand the view, so
  // it resets rather than leaving you on an empty wire.
  useEffect(() => {
    if (filter !== "All" && !inRange.some((i) => i.type === filter)) setFilter("All");
  }, [inRange, filter]);

  useEffect(() => {
    if (model !== "all" && !inRange.some((i) => (i.models || []).includes(model))) setModel("all");
  }, [inRange, model]);

  const earliest = useMemo(
    () => items.map((i) => i.date).sort()[0] || "2026-01-01",
    [items]
  );

  return (
    <div className="wire-root">
      <style>{WIRE_CSS}</style>
      <div className="wire-shell">
        <header className="masthead">
          <div className="eyebrow mono">Primary sources only · LLM systems desk</div>
          <h1>AI WIRE</h1>
          <p style={{ color: "var(--ink-soft)", margin: ".35rem 0 0", fontSize: ".9rem" }}>
            Model releases, API changes, deprecations, pricing and papers, each with the announcement
            behind it. Leave this open and new entries drop in at the top.
          </p>
        </header>

        {/* sections — one entry belongs to exactly one tab */}
        <nav className="tabs" role="tablist" aria-label="Sections">
          {[{ id: "all", label: "Everything" }, ...SECTIONS].map((sec) => (
            <button
              key={sec.id}
              role="tab"
              aria-selected={tab === sec.id}
              className="tab mono"
              data-on={tab === sec.id}
              onClick={() => setTab(sec.id)}
            >
              {sec.label}
              <span className="tabcount">{tabCounts[sec.id] ?? 0}</span>
            </button>
          ))}
        </nav>

        <div className="statusbar mono flex flex-wrap items-center gap-x-4 gap-y-2 px-3 py-2">
          <span>
            <span
              className={"pulse" + (watching ? " live" : "")}
              style={!watching ? { background: "var(--wire)" } : undefined}
            />
            {watching ? `WATCHING · every ${POLL_MINUTES} min` : "WATCH OFF"}
          </span>
          <span>LAST CHECK {fmtClock(lastCheck)}</span>
          <span>{items.length} ENTRIES</span>
          {!isFeedMode && (
            <label className="flex items-center gap-1">
              <span className="sr-only">Model</span>
              {PROVIDERS.length > 1 && (
                <select
                  className="picker mono"
                  value={choice.provider}
                  onChange={(e) => {
                    const p = byId(e.target.value);
                    choose({ provider: p.id, model: p.models[0] });
                  }}
                >
                  {PROVIDERS.map((p) => (
                    <option key={p.id} value={p.id}>
                      {p.label}
                    </option>
                  ))}
                </select>
              )}
              <select
                className="picker mono"
                value={choice.model}
                onChange={(e) => choose({ ...choice, model: e.target.value })}
              >
                {provider.models.map((m) => (
                  <option key={m} value={m}>
                    {m}
                  </option>
                ))}
              </select>
            </label>
          )}
          {!isFeedMode && !provider.supportsSearch && !searchMode && (
            <span className="badge warn">No live search</span>
          )}
          {!isFeedMode && searchMode === "injected" && (
            <span className="badge">Pre-search on</span>
          )}
          <span className="ml-auto flex gap-2">
            <button className="btn ghost" onClick={() => setWatching((w) => !w)}>
              {watching ? "Stop watching" : "Watch for updates"}
            </button>
            <button className="btn" onClick={check} disabled={checking}>
              {checking ? "Checking…" : "Check now"}
            </button>
          </span>
        </div>
        <div className="mono px-3 py-2" style={{ fontSize: ".7rem", color: "var(--ink-soft)" }}>
          {status}
        </div>

        {/* date range */}
        <div className="filterrow flex flex-wrap items-center gap-2 mt-3">
          <span className="filterlabel mono">When</span>
          {RANGES.map((r) => (
            <button
              key={r.id}
              className="chip mono"
              data-on={range.id === r.id}
              onClick={() =>
                setRange((prev) =>
                  r.id === "custom"
                    ? { id: "custom", from: prev.from || earliest, to: prev.to || iso(new Date()) }
                    : { id: r.id, from: "", to: "" }
                )
              }
            >
              {r.label}
            </button>
          ))}
          {range.id === "custom" && (
            <span className="flex items-center gap-1">
              <input
                type="date"
                className="picker mono"
                value={range.from}
                min={earliest}
                max={range.to || undefined}
                onChange={(e) => setRange((p) => ({ ...p, from: e.target.value }))}
                aria-label="From date"
              />
              <span className="mono" style={{ fontSize: ".7rem", color: "var(--ink-soft)" }}>
                to
              </span>
              <input
                type="date"
                className="picker mono"
                value={range.to}
                min={range.from || earliest}
                onChange={(e) => setRange((p) => ({ ...p, to: e.target.value }))}
                aria-label="To date"
              />
            </span>
          )}
        </div>

        {/* type filter — labels come from the model, not a fixed list */}
        <div className="filterrow flex flex-wrap items-center gap-2 mt-2">
          <span className="filterlabel mono">What</span>
          <button className="chip mono" data-on={filter === "All"} onClick={() => setFilter("All")}>
            All · {inRange.filter(matchesModel).length}
          </button>
          {types.map(([t, n]) => (
            <button
              key={t}
              className="chip mono"
              data-on={filter === t}
              onClick={() => setFilter(t)}
            >
              {t} · {n}
            </button>
          ))}
        </div>

        {/* model family — only families actually present are offered */}
        {modelCounts.length > 0 && (
          <div className="filterrow flex flex-wrap items-center gap-2 mt-2">
            <span className="filterlabel mono">Model</span>
            <button className="chip mono" data-on={model === "all"} onClick={() => setModel("all")}>
              Any · {inRange.filter(matchesType).length}
            </button>
            {modelCounts.map(([id, n]) => (
              <button
                key={id}
                className="chip mono"
                data-on={model === id}
                onClick={() => setModel(id)}
              >
                {familyLabel(id)} · {n}
              </button>
            ))}
          </div>
        )}

        <div className="mb-7" />

        <div className="rail">
          {shown.length === 0 && (
            <p className="mono" style={{ fontSize: ".8rem", color: "var(--ink-soft)" }}>
              {inTab.length === 0
                ? "Nothing filed in this section yet. Run a check, or try another tab."
                : inRange.length === 0
                  ? "No entries in that date range. Widen it, or try another tab."
                  : `No ${filter === "All" ? "" : `${filter} `}entries${
                      model === "all" ? "" : ` for ${familyLabel(model)}`
                    } in that date range.`}
            </p>
          )}
          {shown.map((i) => {
            const isNew = newIds.includes(i.id);
            return (
              <article key={i.id} className={"entry" + (isNew ? " fresh" : "")}>
                <span className="node mono" data-new={isNew} aria-hidden="true">
                  {isNew ? "+" : "·"}
                </span>
                <div className="meta mono flex flex-wrap items-center gap-2">
                  <span>{fmtDate(i.date)}</span>
                  <span>{i.source}</span>
                  <span className={"badge" + (i.tier === "Secondary" ? " second" : "")}>
                    {i.tier}
                  </span>
                  <span className="badge second">{i.type}</span>
                  {(i.models || []).map((m) => (
                    <button
                      key={m}
                      className="badge badge-model"
                      onClick={() => setModel(m)}
                      title={`Filter to ${familyLabel(m)}`}
                    >
                      {familyLabel(m)}
                    </button>
                  ))}
                  {i.via && <span className="badge second">via {byId(i.via).label}</span>}
                  {i.flagged && <span className="badge warn">⚑ {i.flagged}</span>}
                  {isNew && <span className="badge warn">New</span>}
                </div>
                <a
                  className="head inline-block mt-1"
                  href={i.url}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  {i.title} ↗
                </a>
                <p>{i.summary}</p>
              </article>
            );
          })}
        </div>

        <footer
          className="mono mt-8 pt-4"
          style={{ fontSize: ".65rem", color: "var(--ink-soft)", borderTop: "1px solid var(--rule)" }}
        >
          Entries are kept on this device between visits. Checks search primary sources and the
          model assigns each entry a type, so the filter row grows as new kinds of news arrive. The
          {isFeedMode
            ? "This site reads a shared feed rebuilt on a schedule, so no key is involved and every visitor sees the same wire. Running it locally in direct mode calls a provider live — "
            : "The provider is swappable — "}
          <a href={provider.docs} target="_blank" rel="noopener noreferrer" style={{ color: "var(--signal)" }}>
            {provider.label} API
          </a>{" "}
          {isFeedMode ? "built the entries below." : "is answering right now."}
        </footer>
      </div>
    </div>
  );
}

export default Wire;
